create extension if not exists pgcrypto;
create table if not exists public.admins (user_id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table if not exists public.services (code text primary key, name text not null, description text not null default '', price_from numeric, unit text not null default 'pekerjaan', min_job numeric, price_note text not null default '', sort_order int not null default 0, active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.inquiries (id uuid primary key default gen_random_uuid(), organization_name text not null, contact_name text not null, email text not null, whatsapp text, organization_type text, location text, volume text, needs text, selected_services text[] not null default '{}', status text not null default 'baru' check (status in ('baru','dihubungi','penawaran','deal','selesai','batal')), estimated_value numeric, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.inquiry_notes (id uuid primary key default gen_random_uuid(), inquiry_id uuid not null references public.inquiries(id) on delete cascade, body text not null, author_id uuid references auth.users(id) on delete set null, created_at timestamptz not null default now());
create table if not exists public.portfolio_items (id uuid primary key default gen_random_uuid(), title text not null, summary text not null default '', service_id text references public.services(code) on delete set null, before_image_url text, after_image_url text, active boolean not null default true, sort_order int not null default 0, created_at timestamptz not null default now());
create table if not exists public.testimonials (id uuid primary key default gen_random_uuid(), quote text not null, author text not null, organization text, active boolean not null default true, sort_order int not null default 0, created_at timestamptz not null default now());
create table if not exists public.settings (key text primary key, value text not null default '');
create or replace function public.set_updated_at() returns trigger language plpgsql set search_path = public as $$ begin new.updated_at=now(); return new; end $$;
drop trigger if exists inquiries_updated_at on public.inquiries; create trigger inquiries_updated_at before update on public.inquiries for each row execute function public.set_updated_at();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.admins where user_id=auth.uid()) $$;
revoke all on function public.is_admin() from public; grant execute on function public.is_admin() to anon, authenticated;
create index if not exists inquiries_status_created_idx on public.inquiries(status, created_at desc); create index if not exists inquiry_notes_inquiry_idx on public.inquiry_notes(inquiry_id);
insert into public.services(code,name,description,price_from,unit,min_job,price_note,sort_order) values ('A','Perapihan Arsip Fisik','Penataan arsip fisik.',200000,'meter linear',null,'Arsip kompleks mulai Rp400.000 / meter linear.',1),('B','Inventaris dan Indeks Arsip','Daftar dan indeks arsip.',2500,'entri',2500000,'Tarif menyesuaikan metadata.',2),('C','Digitalisasi Arsip','Alih media dokumen fisik.',600,'halaman',750000,'OCR mulai Rp1.200 / halaman.',3),('D','Kebutuhan Kearsipan Lainnya','Kebutuhan sesuai lingkup.',null,'lingkup pekerjaan',null,'Penawaran khusus setelah konsultasi.',4) on conflict (code) do nothing;
insert into public.settings(key,value) values ('whatsapp_number',''),('contact_email',''),('business_name','KRTAS'),('hero_text','Arsip tertata. Kerja lebih mudah.') on conflict (key) do nothing;
DO $$ begin create policy "public insert inquiries" on public.inquiries for insert to anon, authenticated with check(status='baru'); exception when duplicate_object then null; end $$;
DO $$ begin create policy "admin all inquiries" on public.inquiries for all to authenticated using(public.is_admin()) with check(public.is_admin()); exception when duplicate_object then null; end $$;
DO $$ begin create policy "public active services" on public.services for select to anon, authenticated using(active or public.is_admin()); create policy "admin all services" on public.services for all to authenticated using(public.is_admin()) with check(public.is_admin()); exception when duplicate_object then null; end $$;
DO $$ begin create policy "public content" on public.portfolio_items for select to anon, authenticated using(active or public.is_admin()); create policy "admin portfolio" on public.portfolio_items for all to authenticated using(public.is_admin()) with check(public.is_admin()); create policy "public testimonials" on public.testimonials for select to anon, authenticated using(active or public.is_admin()); create policy "admin testimonials" on public.testimonials for all to authenticated using(public.is_admin()) with check(public.is_admin()); create policy "public settings" on public.settings for select to anon, authenticated using(key in ('whatsapp_number','contact_email','business_name','hero_text') or public.is_admin()); create policy "admin settings" on public.settings for all to authenticated using(public.is_admin()) with check(public.is_admin()); exception when duplicate_object then null; end $$;
DO $$ begin create policy "admin notes" on public.inquiry_notes for all to authenticated using(public.is_admin()) with check(public.is_admin()); create policy "admin admins" on public.admins for all to authenticated using(public.is_admin()) with check(public.is_admin()); exception when duplicate_object then null; end $$;
alter table public.admins enable row level security; alter table public.services enable row level security; alter table public.inquiries enable row level security; alter table public.inquiry_notes enable row level security; alter table public.portfolio_items enable row level security; alter table public.testimonials enable row level security; alter table public.settings enable row level security;
insert into storage.buckets(id,name,public) values ('portfolio','portfolio',true) on conflict(id) do nothing;
DO $$ begin create policy "public portfolio images" on storage.objects for select using(bucket_id='portfolio'); create policy "admin portfolio uploads" on storage.objects for insert to authenticated with check(bucket_id='portfolio' and public.is_admin()); create policy "admin portfolio updates" on storage.objects for update to authenticated using(bucket_id='portfolio' and public.is_admin()) with check(bucket_id='portfolio' and public.is_admin()); create policy "admin portfolio deletes" on storage.objects for delete to authenticated using(bucket_id='portfolio' and public.is_admin()); exception when duplicate_object then null; end $$;
